--
-- Table structure for table `analysis`
--

DROP TABLE IF EXISTS `analysis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `analysis` (
  `analysis_id` char(12) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'an + 10 digits',
  `mgi_gene_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `allele_id` int unsigned DEFAULT NULL,
  `strain_id` tinyint unsigned NOT NULL,
  `life_stage_id` tinyint unsigned DEFAULT NULL,
  `parameter_stable_id` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `p_value` double DEFAULT NULL,
  `p_value_flag` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'missing | out_of_range_[0,1]',
  `parameter_id_source` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'how the parameter id was validated/recovered',
  `source_file` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `import_issue` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'structural problems repaired at import',
  `analysis_id_note` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content_duplicate_of` char(12) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'first analysis with identical gene/allele/strain/stage/parameter/p-value',
  PRIMARY KEY (`analysis_id`),
  KEY `idx_an_dup` (`content_duplicate_of`),
  KEY `idx_an_gene` (`mgi_gene_id`),
  KEY `idx_an_param` (`parameter_stable_id`),
  KEY `idx_an_param_p` (`parameter_stable_id`,`p_value`),
  KEY `idx_an_gene_p` (`mgi_gene_id`,`p_value`),
  KEY `fk_an_allele` (`allele_id`),
  KEY `fk_an_strain` (`strain_id`),
  KEY `fk_an_stage` (`life_stage_id`),
  CONSTRAINT `fk_an_allele` FOREIGN KEY (`allele_id`) REFERENCES `allele` (`allele_id`),
  CONSTRAINT `fk_an_dup` FOREIGN KEY (`content_duplicate_of`) REFERENCES `analysis` (`analysis_id`),
  CONSTRAINT `fk_an_gene` FOREIGN KEY (`mgi_gene_id`) REFERENCES `gene` (`mgi_gene_id`),
  CONSTRAINT `fk_an_param` FOREIGN KEY (`parameter_stable_id`) REFERENCES `parameter` (`parameter_stable_id`),
  CONSTRAINT `fk_an_stage` FOREIGN KEY (`life_stage_id`) REFERENCES `life_stage` (`life_stage_id`),
  CONSTRAINT `fk_an_strain` FOREIGN KEY (`strain_id`) REFERENCES `strain` (`strain_id`),
  CONSTRAINT `chk_an_id` CHECK (regexp_like(`analysis_id`,_utf8mb4'^an[0-9]{10}$')),
  CONSTRAINT `chk_p_nonneg` CHECK (((`p_value` is null) or (`p_value` >= 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One IMPC statistical analysis (gene knockout x parameter)';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `analysis`
--

LOCK TABLES `analysis` WRITE;
