--
-- Table structure for table `ensembl_gene`
--

DROP TABLE IF EXISTS `ensembl_gene`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ensembl_gene` (
  `ensembl_gene_id` varchar(25) COLLATE utf8mb4_unicode_ci NOT NULL,
  `species_id` tinyint unsigned NOT NULL,
  `gene_name` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`ensembl_gene_id`),
  KEY `idx_eg_name` (`gene_name`),
  KEY `idx_eg_species` (`species_id`),
  CONSTRAINT `fk_eg_species` FOREIGN KEY (`species_id`) REFERENCES `species` (`species_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

