--
-- Table structure for table `gene`
--

DROP TABLE IF EXISTS `gene`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gene` (
  `mgi_gene_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MGI gene accession, e.g. MGI:1859162',
  `gene_symbol` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Official mouse gene symbol',
  `in_impc_data` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = gene has IMPC analyses in this dataset',
  PRIMARY KEY (`mgi_gene_id`),
  KEY `idx_gene_symbol` (`gene_symbol`),
  CONSTRAINT `chk_mgi_format` CHECK (regexp_like(`mgi_gene_id`,_utf8mb4'^MGI:[0-9]+$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Mouse genes (IMPC + MGI disease report)';
/*!40101 SET character_set_client = @saved_cs_client */;

