DROP TABLE IF EXISTS `gene_ensembl_xref`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gene_ensembl_xref` (
  `mgi_gene_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ensembl_gene_id` varchar(25) COLLATE utf8mb4_unicode_ci NOT NULL,
  `match_method` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`mgi_gene_id`,`ensembl_gene_id`),
  KEY `idx_gex_ens` (`ensembl_gene_id`),
  CONSTRAINT `fk_gex_ens` FOREIGN KEY (`ensembl_gene_id`) REFERENCES `ensembl_gene` (`ensembl_gene_id`),
  CONSTRAINT `fk_gex_gene` FOREIGN KEY (`mgi_gene_id`) REFERENCES `gene` (`mgi_gene_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Links MGI genes to mouse Ensembl genes';
/*!40101 SET character_set_client = @saved_cs_client */;

