DROP TABLE IF EXISTS `human_gene_disease`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `human_gene_disease` (
  `hgnc_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `doid` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`hgnc_id`,`doid`),
  KEY `idx_hgd_doid` (`doid`),
  CONSTRAINT `fk_hgd_dis` FOREIGN KEY (`doid`) REFERENCES `disease` (`doid`),
  CONSTRAINT `fk_hgd_gene` FOREIGN KEY (`hgnc_id`) REFERENCES `human_gene` (`hgnc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

