--
-- Table structure for table `parameter`
--

DROP TABLE IF EXISTS `parameter`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `parameter` (
  `parameter_stable_id` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'IMPReSS parameter stable id',
  `parameter_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parameter_description` text COLLATE utf8mb4_unicode_ci,
  `procedure_id` smallint unsigned DEFAULT NULL,
  `procedure_link` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IMPC_reference | inferred_from_procedure_code',
  `is_mandatory` tinyint(1) DEFAULT NULL,
  `in_impc_reference` tinyint(1) NOT NULL COMMENT '1 = present in supplied IMPC parameter reference',
  PRIMARY KEY (`parameter_stable_id`),
  KEY `idx_param_name` (`parameter_name`),
  KEY `idx_param_proc` (`procedure_id`),
  CONSTRAINT `fk_param_proc` FOREIGN KEY (`procedure_id`) REFERENCES `procedure` (`procedure_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Phenotyping parameters (reference + centre-specific ids used in data)';
/*!40101 SET character_set_client = @saved_cs_client */;

