CREATE TABLE `parameter_group` (
  `group_id` smallint unsigned NOT NULL,
  `group_name` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `group_description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rule_description` text COLLATE utf8mb4_unicode_ci COMMENT 'how membership was assigned (reproducible rule)',
  PRIMARY KEY (`group_id`),
  UNIQUE KEY `uq_group_name` (`group_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
