DROP TABLE IF EXISTS `procedure`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `procedure` (
  `procedure_id` smallint unsigned NOT NULL,
  `procedure_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `procedure_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IMPReSS code, e.g. OFD',
  `description` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`procedure_id`),
  UNIQUE KEY `uq_procedure_name` (`procedure_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IMPC phenotyping procedures (IMPReSS)';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `procedure`
--

LOCK TABLES `procedure` WRITE;
/*!40000 ALTER TABLE `procedure` DISABLE KEYS */;
INSERT INTO `procedure` VALUES (1,'Acoustic Startle and Pre-pulse Inhibition (PPI)','ACS',NULL),(2,'Adult LacZ','ALZ',NULL),(3,'Auditory Brain Stem Response','ABR','Auditory brainstem response test determines hearing sensitivity and other physiological parameters using evoked potential recordings in anesthetized mice.Ontological description: MP:0004738 - abnormal brainstem auditory evoked potential.'),(4,'Body Composition (DEXA lean/fat)','DXA','Measure bone mineral content and density as well as body composition in mice using the DEXA (Dual Energy X-ray Absorptiometry) analyser.'),(5,'Body Weight','BWT',NULL),(6,'Challenge Whole Body Plethysmography','CHL',NULL),(7,'Clinical Chemistry','CBC',NULL),(8,'Combined SHIRPA and Dysmorphology','CSD','SHIRPA and dysmorphology were originally always separate assessments.&nbsp; However they have recently been combined as assessments so that they take place at the same time.The purpose of the assessments is to examine mice for obvious physical characteristics behaviors and morphological abnormalities.Descriptions include abnormal locomotion/appearance/behavior/reflex reactions.'),(9,'Echo','ECH','To assess the functionality of the heart in order to determine the presence of a mutant phenotype.'),(10,'Electrocardiogram (ECG)','ECG','To provide a high throughput method to obtain Electrocardiograms in a conscious mouse.'),(11,'Embryo LacZ','ELZ',NULL),(12,'Experimental design','EXD',NULL),(13,'Eye Morphology','EYE','To detect abnormalities in eye morphology.'),(14,'Fear Conditioning','FEA','Fear Conditioning test assesses aversive learning and memory'),(15,'Fertility of Homozygous Knock-out Mice','FER','To assess the fertility of homozygous knockout mice.'),(16,'Formalin Test','FOR',NULL),(17,'Grip Strength','GRS',NULL),(18,'Gross Morphology Embryo E12.5','GEM',NULL),(19,'Gross Morphology Embryo E14.5-E15.5','GEO',NULL),(20,'Gross Morphology Embryo E18.5','GEP',NULL),(21,'Gross Morphology Embryo E9.5','GEL',NULL),(22,'Gross Morphology Placenta E12.5','GPM',NULL),(23,'Gross Morphology Placenta E14.5-E15.5','GPO',NULL),(24,'Gross Morphology Placenta E18.5','GPP',NULL),(25,'Gross Morphology Placenta E9.5','GPL',NULL),(26,'Gross Pathology and Tissue Collection','PAT',NULL),(27,'Heart Weight','HWT','To evaluate cardiac size using heart weight and body weight.'),(28,'Hematology','HEM','Hematological assessment of blood determines blood cell counts (white blood cells red blood cells hemoglobin and platelets) and additional hematological parameters (hematocrit mean cell volume mean corpuscular hemoglobin mean cell hemoglobin concentration) can be derived using these indices. These tests will indicate abnormalities in the production of blood and its components (blood cells and hemoglobin) as well as in the associated blood-forming organs.&nbsp;Ontological description: MP:0002429 - abnormal blood cell morphology/development.'),(29,'Histopathology','HIS',NULL),(30,'Housing and Husbandry','HOU',NULL),(31,'Immunophenotyping','IMM','Immunophenotyping of immune system cells'),(32,'Indirect Calorimetry','CAL',NULL),(33,'Insulin Blood Level','INS','The insulin concentration in the blood is an important indicator of diabetes.Ontological description: abnormal circulating insulin level [MP:0001560]; increased circulating insulin level [MP:0002079]; decreased circulating insulin level [MP:0002727].'),(34,'Intraperitoneal glucose tolerance test (IPGTT)','IPG',NULL),(35,'Light-Dark Test','LDT','Light-Dark test monitors the anxiety-related behaviour of mice'),(36,'MicroCT E14.5-E15.5','EMO',NULL),(37,'MicroCT E14.5-E15.5 Analysis','MAA',NULL),(38,'MicroCT E18.5','EMA',NULL),(39,'MicroCT E9.5','EML',NULL),(40,'OPT E9.5','EOL',NULL),(41,'Open Field','OFD','The Open Field test is used to assess anxiety and exploratory behaviors. It is based on the natural tendency of an animal to explore and to protect itself using avoidance which translates to a normal animal spending more time in the periphery of the Open Field arena than in the center (the most anxiogenic area).'),(42,'Organ Weight','OWT','Organ weights from different tissues collected for IMPC'),(43,'Tissue Embedding and Block Banking','BLK','Collect and fix a standard list of tissues from the complete necropsy (see IMPC Gross Pathology &amp; Tissue Collection SOP)Trim the fixed tissues into cassettes for processingEmbed the tissues in paraffin in a standard orientation'),(44,'Viability E12.5 Secondary Screen','EVM',NULL),(45,'Viability E14.5-E15.5 Secondary Screen','EVO',NULL),(46,'Viability E18.5 Secondary Screen','EVP',NULL),(47,'Viability E9.5 Secondary Screen','EVL',NULL),(48,'Viability Primary Screen','VIA','Assess the viability of mutant mice of each sex and zygosity.'),(49,'Welfare Observations','WEL','The Welfare Observations procedure is used for the recording of welfare issues as and when they occur.'),(50,'X-ray','XRY','Construct and analyse digital X-ray images in immobilised mice using a Faxitron X-Ray system or NTB digital X-ray scanner.'),(51,'Y-maze','YMZ','Y-maze assesses learning and memory; it can be used instead/in parallel of Fear Conditioning');
/*!40000 ALTER TABLE `procedure` ENABLE KEYS */;
UNLOCK TABLES;

